-- Runs on every startup (spring.sql.init.mode=always), so every statement must be idempotent.
-- Tables follow the QC-18 contract, section 2 (domain model). Ids are GENERATED BY DEFAULT so the
-- QC-20 seed (data.sql) can pin the contract's example ids (quiz 101, revision 1001, ...).

CREATE TABLE IF NOT EXISTS categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'RETIRED'))
);
-- Databases created before QC-20 used GENERATED ALWAYS.
ALTER TABLE categories ALTER COLUMN id SET GENERATED BY DEFAULT;

CREATE TABLE IF NOT EXISTS users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(320) NOT NULL UNIQUE,
    display_name VARCHAR(100) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    role VARCHAR(16) NOT NULL DEFAULT 'USER' CHECK (role IN ('USER', 'ADMIN'))
);

CREATE TABLE IF NOT EXISTS quizzes (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id BIGINT NOT NULL REFERENCES users (id),
    status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'REMOVED')),
    latest_published_revision_id BIGINT
);

-- Drafts may be incomplete. A PUBLISHED revision must carry everything the catalog shows.
CREATE TABLE IF NOT EXISTS quiz_revisions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    quiz_id BIGINT NOT NULL REFERENCES quizzes (id),
    number INT,
    state VARCHAR(16) NOT NULL CHECK (state IN ('DRAFT', 'PUBLISHED')),
    title VARCHAR(200),
    description TEXT,
    category_id BIGINT REFERENCES categories (id),
    difficulty VARCHAR(16) CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    published_at TIMESTAMPTZ,
    UNIQUE (quiz_id, number),
    CHECK (state = 'DRAFT' OR (number IS NOT NULL AND title IS NOT NULL AND category_id IS NOT NULL
                               AND difficulty IS NOT NULL AND published_at IS NOT NULL))
);
-- Contract: at most one DRAFT per quiz.
CREATE UNIQUE INDEX IF NOT EXISTS quiz_revisions_one_draft_per_quiz
    ON quiz_revisions (quiz_id) WHERE state = 'DRAFT';

-- quizzes <-> quiz_revisions reference each other, so this foreign key is added after both tables.
ALTER TABLE quizzes DROP CONSTRAINT IF EXISTS quizzes_latest_published_revision_fk;
ALTER TABLE quizzes ADD CONSTRAINT quizzes_latest_published_revision_fk
    FOREIGN KEY (latest_published_revision_id) REFERENCES quiz_revisions (id);

CREATE TABLE IF NOT EXISTS questions (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    revision_id BIGINT NOT NULL REFERENCES quiz_revisions (id),
    position INT NOT NULL,
    type VARCHAR(16) NOT NULL CHECK (type IN ('MULTIPLE_CHOICE', 'TRUE_FALSE')),
    text TEXT NOT NULL,
    UNIQUE (revision_id, position)
);

CREATE TABLE IF NOT EXISTS choices (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question_id BIGINT NOT NULL REFERENCES questions (id),
    position INT NOT NULL,
    text VARCHAR(500) NOT NULL,
    is_correct BOOLEAN NOT NULL DEFAULT FALSE,
    UNIQUE (question_id, position)
);

-- Attempts (contract section 2). QC-29 grades and saves them (play/AttemptStore). QC-31 reads them back
-- (attempt/AttemptHistory). One row per submission, so a retake is a new attempt. An attempt points at the
-- immutable published revision it was graded against, with one answer per question (choice_id NULL = blank),
-- so history never depends on later edits. Ids start at 7001 to match the contract's examples.
CREATE TABLE IF NOT EXISTS attempts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 7001) PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users (id),
    revision_id BIGINT NOT NULL REFERENCES quiz_revisions (id),
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT statement_timestamp(),
    score INT NOT NULL,
    max_score INT NOT NULL,
    CHECK (score >= 0 AND score <= max_score)
);
-- My history: one owner's attempts, newest first.
CREATE INDEX IF NOT EXISTS attempts_history ON attempts (user_id, submitted_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS attempt_answers (
    attempt_id BIGINT NOT NULL REFERENCES attempts (id),
    question_id BIGINT NOT NULL REFERENCES questions (id),
    choice_id BIGINT REFERENCES choices (id),
    correct BOOLEAN NOT NULL,
    PRIMARY KEY (attempt_id, question_id),
    CHECK (choice_id IS NOT NULL OR NOT correct)
);
